kIn = input(7, "K Neighbors", 1, 15, 1)
featLen = input(20, "Feature Lookback", 5, 40, 1)
compWin = input(200, "Comparison Window", 50, 500, 10)
marginThresh = input(3, "Margin Threshold", 1, 7, 1)
disagThresh = input(0.35, "Disagreement Threshold", 0.05, 0.9, 0.05)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Per-bar feature element: close-to-close change ───
fVal = 0.0
if bar_index > 0 {
    denom = close[1] + 0.000000001
    fVal := (close - close[1]) / denom
}

// ─── Comparison depth from live bar count (no frozen var) ───
maxLag = bar_index - featLen - 1
if maxLag > compWin {
    maxLag := compWin
}

// ─── KNN vote (recomputed every bar from series history) ───
upCount = 0
downCount = 0
margin = 0.0
disag = 1.0
conf = 0.0
spread = 0.0
meanD = 0.0
bestD0 = 999999.0
bestD1 = 999999.0
bestD2 = 999999.0
bestD3 = 999999.0
bestD4 = 999999.0
bestD5 = 999999.0
bestD6 = 999999.0
bestL0 = 0
bestL1 = 0
bestL2 = 0
bestL3 = 0
bestL4 = 0
bestL5 = 0
bestL6 = 0

if maxLag >= 1 {
    lag = 1
    while (lag <= maxLag) {
        sumSq = 0.0
        ei = 0
        while (ei < featLen) {
            aI = ei
            bI = lag + 1 + ei
            curF = fVal[aI]
            pastF = fVal[bI]
            diff = curF - pastF
            sumSq := sumSq + diff * diff
            ei := ei + 1
        }
        dist = sqrt(sumSq)
        cA = close[lag]
        cB = close[lag + 1]
        lbl = 0 - 1
        if cA > cB {
            lbl := 1
        }
        if dist < bestD0 {
            bestD6 := bestD5
            bestL6 := bestL5
            bestD5 := bestD4
            bestL5 := bestL4
            bestD4 := bestD3
            bestL4 := bestL3
            bestD3 := bestD2
            bestL3 := bestL2
            bestD2 := bestD1
            bestL2 := bestL1
            bestD1 := bestD0
            bestL1 := bestL0
            bestD0 := dist
            bestL0 := lbl
        } else {
            if dist < bestD1 {
                bestD6 := bestD5
                bestL6 := bestL5
                bestD5 := bestD4
                bestL5 := bestL4
                bestD4 := bestD3
                bestL4 := bestL3
                bestD3 := bestD2
                bestL3 := bestL2
                bestD2 := bestD1
                bestL2 := bestL1
                bestD1 := dist
                bestL1 := lbl
            } else {
                if dist < bestD2 {
                    bestD6 := bestD5
                    bestL6 := bestL5
                    bestD5 := bestD4
                    bestL5 := bestL4
                    bestD4 := bestD3
                    bestL4 := bestL3
                    bestD3 := bestD2
                    bestL3 := bestL2
                    bestD2 := dist
                    bestL2 := lbl
                } else {
                    if dist < bestD3 {
                        bestD6 := bestD5
                        bestL6 := bestL5
                        bestD5 := bestD4
                        bestL5 := bestL4
                        bestD4 := bestD3
                        bestL4 := bestL3
                        bestD3 := dist
                        bestL3 := lbl
                    } else {
                        if dist < bestD4 {
                            bestD6 := bestD5
                            bestL6 := bestL5
                            bestD5 := bestD4
                            bestL5 := bestL4
                            bestD4 := dist
                            bestL4 := lbl
                        } else {
                            if dist < bestD5 {
                                bestD6 := bestD5
                                bestL6 := bestL5
                                bestD5 := dist
                                bestL5 := lbl
                            } else {
                                if dist < bestD6 {
                                    bestD6 := dist
                                    bestL6 := lbl
                                }
                            }
                        }
                    }
                }
            }
        }
        lag := lag + 1
    }
    u = 0
    d = 0
    if bestD0 < 999998.0 {
        if bestL0 == 1 {
            u := u + 1
        } else {
            d := d + 1
        }
    }
    if bestD1 < 999998.0 {
        if bestL1 == 1 {
            u := u + 1
        } else {
            d := d + 1
        }
    }
    if bestD2 < 999998.0 {
        if bestL2 == 1 {
            u := u + 1
        } else {
            d := d + 1
        }
    }
    if bestD3 < 999998.0 {
        if bestL3 == 1 {
            u := u + 1
        } else {
            d := d + 1
        }
    }
    if bestD4 < 999998.0 {
        if bestL4 == 1 {
            u := u + 1
        } else {
            d := d + 1
        }
    }
    if bestD5 < 999998.0 {
        if bestL5 == 1 {
            u := u + 1
        } else {
            d := d + 1
        }
    }
    if bestD6 < 999998.0 {
        if bestL6 == 1 {
            u := u + 1
        } else {
            d := d + 1
        }
    }
    upCount := u
    downCount := d
    margin := (u - d) * 1.0
    absM = abs(margin)
    disag := 1.0 - absM / (kIn * 1.0)
    normM = margin / (kIn * 1.0)
    conf := normM * (1.0 - disag)
    md = 0.0
    cntD = 0
    if bestD0 < 999998.0 {
        md := md + bestD0
        cntD := cntD + 1
    }
    if bestD1 < 999998.0 {
        md := md + bestD1
        cntD := cntD + 1
    }
    if bestD2 < 999998.0 {
        md := md + bestD2
        cntD := cntD + 1
    }
    if bestD3 < 999998.0 {
        md := md + bestD3
        cntD := cntD + 1
    }
    if bestD4 < 999998.0 {
        md := md + bestD4
        cntD := cntD + 1
    }
    if bestD5 < 999998.0 {
        md := md + bestD5
        cntD := cntD + 1
    }
    if bestD6 < 999998.0 {
        md := md + bestD6
        cntD := cntD + 1
    }
    if cntD > 0 {
        md := md / cntD
        meanD := md
        vsum = 0.0
        if bestD0 < 999998.0 {
            dd0 = bestD0 - md
            vsum := vsum + dd0 * dd0
        }
        if bestD1 < 999998.0 {
            dd1 = bestD1 - md
            vsum := vsum + dd1 * dd1
        }
        if bestD2 < 999998.0 {
            dd2 = bestD2 - md
            vsum := vsum + dd2 * dd2
        }
        if bestD3 < 999998.0 {
            dd3 = bestD3 - md
            vsum := vsum + dd3 * dd3
        }
        if bestD4 < 999998.0 {
            dd4 = bestD4 - md
            vsum := vsum + dd4 * dd4
        }
        if bestD5 < 999998.0 {
            dd5 = bestD5 - md
            vsum := vsum + dd5 * dd5
        }
        if bestD6 < 999998.0 {
            dd6 = bestD6 - md
            vsum := vsum + dd6 * dd6
        }
        vsum := vsum / cntD
        sd = sqrt(vsum)
        spread := sd / (md + 0.000000001)
    }
}

if maxLag < 1 {
    margin := 0.0
    disag := 1.0
    conf := 0.0
    spread := 0.0
    meanD := 0.0
    upCount := 0
    downCount := 0
}

// ─── Signal states: both channels must agree ───
