plot3d(disagScaled, "Disagreement Cloud", "scatter", "#ffd43b", "separate", 1)

// Volume Session Value Signal Analysis Model
// Volume-profile-at-price engine: POC + value area from session range.

rowsIn = input(24, "Rows", 10, 48, 1)
vaPctIn = input(70, "Value Area %", 50, 90, 5)
sessLen = input(120, "Session Length", 30, 300, 10)
show3D = input(true, "Show 3D")
show2D = input(true, "Show 2D")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Session range ───────────────────────────────────────────────
hh = highest(high, sessLen)
ll = lowest(low, sessLen)
rng = hh - ll
if rng <= 0 {
    rng := close * 0.01
}
rowH = rng / rowsIn

// ─── Per-bar volume-at-price rows (fresh each bar) ───────────────
rowVol = array()
k = 0
while k < rowsIn {
    array.push(rowVol, 0.0)
    k := k + 1
}

j = 0
while j < sessLen {
    bHigh = high[j]
    bLow = low[j]
    bVol = volume[j]
    r1 = floor((bLow - ll) / rng * rowsIn)
    r2 = floor((bHigh - ll) / rng * rowsIn)
    if r1 < 0 {
        r1 := 0
    }
    if r2 < 0 {
        r2 := 0
    }
    if r1 > rowsIn - 1 {
        r1 := rowsIn - 1
    }
    if r2 > rowsIn - 1 {
        r2 := rowsIn - 1
    }
    n = r2 - r1 + 1
    if n < 1 {
        n := 1
    }
    share = bVol / n
    r = r1
    while r <= r2 {
        array.set(rowVol, r, array.get(rowVol, r) + share)
        r := r + 1
    }
    j := j + 1
}

totalVol = array.sum(rowVol)
if totalVol <= 0 {
    totalVol := 1.0
}

// ─── POC: row with max volume ────────────────────────────────────
pocRow = 0
pocVol = array.get(rowVol, 0)
i = 1
while i < rowsIn {
    v = array.get(rowVol, i)
    if v > pocVol {
        pocVol := v
        pocRow := i
    }
    i := i + 1
}
pocShare = pocVol / totalVol
pocPrice = ll + (pocRow + 0.5) / rowsIn * rng

// ─── Value area: sort rows by volume desc, accumulate to vaPct ───
picked = array()
p = 0
while p < rowsIn {
    array.push(picked, 0.0)
    p := p + 1
}
accum = 0.0
target = totalVol * vaPctIn / 100
vaLowRow = pocRow
vaHighRow = pocRow
guard = 0
while accum < target and guard < rowsIn {
    best = 0 - 1
    bestV = 0 - 1.0
    s = 0
    while s < rowsIn {
        if array.get(picked, s) == 0.0 {
            sv = array.get(rowVol, s)
            if sv > bestV {
                bestV := sv
                best := s
            }
        }
        s := s + 1
    }
    if best < 0 {
        guard := rowsIn
    } else {
        array.set(picked, best, 1.0)
        accum := accum + bestV
        if best < vaLowRow {
            vaLowRow := best
        }
        if best > vaHighRow {
            vaHighRow := best
        }
        guard := guard + 1
    }
}
vahPrice = ll + (vaHighRow + 1) / rowsIn * rng
valPrice = ll + vaLowRow / rowsIn * rng
vaWidth = vahPrice - valPrice
if vaWidth <= 0 {
    vaWidth := rowH
}
vaMid = (vahPrice + valPrice) / 2
insideVA = close >= valPrice and close <= vahPrice
insidePrev = close[1] >= valPrice[1] and close[1] <= valPrice[1] + (vahPrice[1] - valPrice[1])

// ─── Signals: price leaving value ────────────────────────────────
buySig = close > vahPrice and insidePrev and not insideVA
sellSig = close < valPrice and insidePrev and not insideVA

// ─── Price-denominated 3D terrain carriers (same value info) ─────
profTerrain = pocPrice + pocShare * rng * 0.5
vaPlateau = vaMid + (pocShare - 0.15) * vaWidth

// ─── Signal markers (2D) ─────────────────────────────────────────
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}

// ─── 3D signal markers + POC rail label (same pane) ──────────────
if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 2, "3d")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 2, "3d")
}

// ─── 2D carries identical POC / VAH / VAL ─────────────────────────
plot(close, "Close", "#ffffff", 1)
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(pocShare * 100, "POC Share %", "#ffd43b", 1, "separate")
plot(vaWidth / rng * 100, "VA Width %", "#4488ff", 1, "separate")

// ─── 3D terrain + plateau + labelled POC rail ─────────────────────
plot3d(profTerrain, "Value Terrain", "manifold", "#22cc88", "3d", 0)
plot3d(vaPlateau, "Value Plateau", "surface", "#4488ff", "3d", 1)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 2)
label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.0, 2, "3d")

// FIX 1: var lvl = highest(high, 20) froze the level on bar 0 — var initializers run once, so it must be a plain assignment.
// FIX 2: close[-1] reads a future bar that does not exist yet (lookahead leak) — corrected to close > lvl on the current bar.
// FIX 3: plotshape(true, low, "Buy", shape.triangleup, color.green) is PineScript — OakScript uses positional (bar_index, price, title, style, color) with quoted strings.
// FIX 4: plot3d(r, "RSI", "surface", "#b48cff", "3d") forces an oscillator into the price scene — oscillators must use pane "separate".
lvlLen = input(20, "Level Length", 1, 100, 1)
rsiLen = input(14, "RSI Length", 1, 100, 1)
osLvl = input(30, "Oversold Level", 1, 100, 1)
lvl = highest(high, lvlLen)
r = rsi(close, rsiLen)
buySig = close > lvl
osSig = crossover(r, osLvl)
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if osSig {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}
plot(lvl, "Level", "#ffcc44", 1, "stepline", "main")
plot(r, "RSI", "#b48cff", 1, "line", "separate")
plot3d(r, "RSI", "surface", "#b48cff", "separate")

windX = input(1.0, "Wind Direction X", -5.0, 5.0, 0.1)
windY = input(0.0, "Wind Direction Y", -5.0, 5.0, 0.1)
windZ = input(0.0, "Wind Direction Z", -5.0, 5.0, 0.1)
windSpeedIn = input(10.0, "Wind Speed Knots", 0.0, 100.0, 0.5)
minSpeed = input(0.0, "Min Speed Knots", 0.0, 50.0, 0.5)
maxSpeed = input(50.0, "Max Speed Knots", 5.0, 100.0, 0.5)
baseTail = input(1.0, "Base Tail Length", 0.2, 5.0, 0.1)
lenPerKnot = input(0.1, "Length Per Knot", 0.01, 0.5, 0.01)
alertHigh = input(30.0, "High Wind Alert Knots", 5.0, 100.0, 0.5)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

drift = (close - open) * 0.05
driftY = (high - low) * 0.02
driftZ = (close - close[1]) * 0.03
xEff = windX + drift * 0.01
yEff = windY + driftY * 0.01
zEff = windZ + driftZ * 0.01
speedEff = windSpeedIn + drift

mag = sqrt(xEff * xEff + yEff * yEff + zEff * zEff)
safeMag = mag
if mag == 0 {
    safeMag = 0.000001
}
nx = xEff / safeMag
ny = yEff / safeMag
nz = zEff / safeMag

qyaw = 0.0
if nx > 0 {
    qyaw = ny / nx
}
if nx < 0 {
    qyaw = ny / nx
}
aqyaw = abs(qyaw)
atanYawQ = qyaw / (1.0 + 0.28 * qyaw * qyaw)
if aqyaw > 1 {
    invYaw = 1.0 / aqyaw
    smallYaw = invYaw / (1.0 + 0.28 * invYaw * invYaw)
    largeYaw = 1.5707963 - smallYaw
    atanYawQ = largeYaw
    if qyaw < 0 {
        atanYawQ = 0.0 - largeYaw
    }
}
yawRad = atanYawQ
if nx < 0 {
    yawRad = atanYawQ + 3.14159265
    if ny < 0 {
        yawRad = atanYawQ - 3.14159265
    }
}
if nx == 0 {
    yawRad = 0.0
    if ny > 0 {
        yawRad = 1.5707963
    }
    if ny < 0 {
        yawRad = 0.0 - 1.5707963
    }
}
horiz = sqrt(nx * nx + ny * ny)
qpitch = 0.0
if horiz > 0 {
    qpitch = nz / horiz
}
aqpitch = abs(qpitch)
atanPitchQ = qpitch / (1.0 + 0.28 * qpitch * qpitch)
if aqpitch > 1 {
    invPitch = 1.0 / aqpitch
    smallPitch = invPitch / (1.0 + 0.28 * invPitch * invPitch)
    largePitch = 1.5707963 - smallPitch
    atanPitchQ = largePitch
    if qpitch < 0 {
        atanPitchQ = 0.0 - largePitch
    }
}
pitchRad = atanPitchQ
if horiz == 0 {
    pitchRad = 0.0
    if nz > 0 {
        pitchRad = 1.5707963
    }
    if nz < 0 {
        pitchRad = 0.0 - 1.5707963
    }
}
yawDeg = yawRad * 57.29578
pitchDeg = pitchRad * 57.29578
rollDeg = 0.0

tailLen = baseTail + lenPerKnot * speedEff
span = maxSpeed - minSpeed
tRaw = (speedEff - minSpeed) / span
tClamp = tRaw
if tRaw < 0 {
    tClamp = 0.0
}
if tRaw > 1 {
    tClamp = 1.0
}
rVal = tClamp
gVal = 0.2 * (1.0 - tClamp) + 0.5 * tClamp
bVal = 1.0 * (1.0 - tClamp)

var prevYaw = 0.0
var prevPitch = 0.0
useYaw = yawDeg
usePitch = pitchDeg
if mag == 0 {
    useYaw = prevYaw
    usePitch = prevPitch
}
yawChg = abs(useYaw - useYaw[1])
pitchChg = abs(usePitch - usePitch[1])

highWindSig = crossover(speedEff, alertHigh)
calmLevel = minSpeed + 2.0
calmSig = crossunder(speedEff, calmLevel)
orientSig = yawChg > 15.0 or pitchChg > 15.0

if mag == 0 {
    prevYaw := prevYaw
    prevPitch := prevPitch
}
if mag > 0 {
    prevYaw := useYaw
    prevPitch := usePitch
}

arrowCol = "#2266ff"
if tClamp > 0.5 {
    arrowCol = "#ff8800"
}
if tClamp > 0.25 {
    if tClamp <= 0.5 {
        arrowCol = "#8844cc"
    }
}

coneSize = tailLen * 0.5 * markerSize
if coneSize < 0.2 {
    coneSize = 0.2
}
if coneSize > 3.0 {
    coneSize = 3.0
}

if highWindSig {
    plotshape(bar_index, high, "HighWind", "triangledown", "#ff8800")
}
if calmSig {
    plotshape(bar_index, low, "Calm", "triangleup", "#2266ff")
}
if orientSig {
    plotshape(bar_index, low, "Shift", "diamond", "#ff8800")
}

plot(speedEff, "Wind Speed kn", "#ff8800", 2, "separate")
plot(tailLen, "Tail Length", "#2266ff", 1, "separate")
plot(useYaw, "Yaw deg", "#33ccff", 1, "separate")

plot3d(speedEff, "Wind Speed", "ribbon", "#ff8800", "separate")
plot3d(tailLen, "Tail Length", "line3d", "#2266ff", "separate", 1)

if highWindSig {
    plotshape_3d(bar_index, high, "HighWind", "coneup", "#ff8800", coneSize, 0, "separate", usePitch, useYaw, rollDeg)
}
if calmSig {
    plotshape_3d(bar_index, low, "Calm", "conedown", "#2266ff", coneSize, 1, "separate", usePitch, useYaw, rollDeg)
}
if orientSig {
    plotshape_3d(bar_index, close, "Shift", "diamond", "#ff8800", coneSize, 2, "separate", usePitch, useYaw, rollDeg)
}

arrowX2 = 5.0 * tailLen * nx
arrowY2 = tailLen * ny
arrow.new(0, 0, arrowX2, arrowY2, arrowCol, 2, "windArrow")

flowSrc = input(close, "Flow PSI Source")
crit = input(150, "Critical Threshold", 10, 500, 1)
spinF = input(1.0, "Spin Factor", 0.1, 5.0, 0.1)
numRings = input(5, "Num Shockwave Rings", 1, 8, 1)
expSpeed = input(2.0, "Ring Expansion Speed", 0.1, 10.0, 0.1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

flow_psi = flowSrc
spin_speed = flow_psi * spinF
spinNorm = spin_speed / 100
expNorm = expSpeed / 10
ringBase = flow_psi + expNorm * 4
ringOuter = flow_psi + expNorm * 10 + spinNorm * 2
locked = flow_psi > crit

var rot = 0.0
var lockT = 0.0

rot := rot[1] + spinNorm
lockT := lockT[1] + 1
if locked {
    rot := rot[1]
}
if locked {
    lockT := lockT[1] + 1
} else {
    lockT := 0.0
}
discSpin = rot
shockFront = flow_psi + lockT * expNorm

lockSig = locked and not locked[1]
resetSig = not locked and locked[1]

if lockSig {
    plotshape(bar_index, high, "Overpressure", "triangledown", "#ff4477")
}
if resetSig {
    plotshape(bar_index, low, "Reset", "triangleup", "#22cc88")
}
if lockSig {
    plotshape_3d(bar_index, flow_psi, "ValveLock", "torus", "#ff4477", 1.0 * markerSize, 0, "separate", 0, discSpin, 0)
}
if lockSig {
    plotshape_3d(bar_index, flow_psi, "Ring1", "torus", "#ff8833", 0.6 * markerSize, 1, "separate", 0, discSpin, 0)
}
if lockSig {
    plotshape_3d(bar_index, flow_psi, "Ring2", "torus", "#ffaa33", 1.0 * markerSize, 2, "separate", 0, discSpin, 0)
}
if lockSig {
    plotshape_3d(bar_index, flow_psi, "Ring3", "torus", "#ffcc33", 1.4 * markerSize, 3, "separate", 0, discSpin, 0)
}
if lockSig {
    plotshape_3d(bar_index, flow_psi, "Ring4", "torus", "#ffee33", 1.8 * markerSize, 4, "separate", 0, discSpin, 0)
}
